package com.bank.alert.service;

import com.bank.alert.dto.AlertResult;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import java.util.*;
import java.util.stream.IntStream;

@Service
@Slf4j
public class AlertService {

    // 100K transactions — suspicious ones at known positions
    private final List<String> transactions;

    public AlertService() {
        transactions = new ArrayList<>(100_000);
        for (int i = 1; i <= 100_000; i++) {
            // Suspicious transactions at positions 500, 25000, 50000, 75000
            String status = (i == 500 || i == 25_000 || i == 50_000 || i == 75_000)
                ? "SUSPICIOUS" : "NORMAL";
            transactions.add("TXN-" + String.format("%06d", i) + ":" + status);
        }
    }

    // ═══ findFirst — deterministic, FIRST suspicious in order ═══
    public AlertResult findFirstSuspicious() {
        long start = System.nanoTime();

        Optional<String> result = transactions.parallelStream()
            .filter(t -> t.contains("SUSPICIOUS"))
            .findFirst();  // always TXN-000500 (first in source order)

        long duration = System.nanoTime() - start;

        return new AlertResult("parallelStream().findFirst()",
            result.orElse("none"), true, duration,
            "Always returns TXN-000500 — the FIRST suspicious in source order. " +
            "Parallel threads coordinate to ensure no earlier match exists.");
    }

    // ═══ findAny — non-deterministic, ANY suspicious (fastest thread) ═══
    public AlertResult findAnySuspicious() {
        long start = System.nanoTime();

        Optional<String> result = transactions.parallelStream()
            .filter(t -> t.contains("SUSPICIOUS"))
            .findAny();  // could be TXN-000500, TXN-025000, TXN-050000, or TXN-075000

        long duration = System.nanoTime() - start;

        return new AlertResult("parallelStream().findAny()",
            result.orElse("none"), false, duration,
            "Returns whichever suspicious TXN a thread finds first — non-deterministic. " +
            "No coordination between threads — faster!");
    }

    // ═══ Sequential — both identical ═══
    public AlertResult findFirstSequential() {
        long start = System.nanoTime();
        Optional<String> first = transactions.stream().filter(t -> t.contains("SUSPICIOUS")).findFirst();
        long dur1 = System.nanoTime() - start;

        start = System.nanoTime();
        Optional<String> any = transactions.stream().filter(t -> t.contains("SUSPICIOUS")).findAny();
        long dur2 = System.nanoTime() - start;

        return new AlertResult("stream() — both identical",
            "findFirst=" + first.orElse("") + " findAny=" + any.orElse(""),
            true, dur1 + dur2,
            "In sequential streams: findFirst and findAny return the SAME element (TXN-000500)");
    }
}
