package com.bank.alert.controller;

import com.bank.alert.dto.AlertResult;
import com.bank.alert.service.AlertService;
import lombok.RequiredArgsConstructor;
import org.springframework.web.bind.annotation.*;

@RestController
@RequestMapping("/api/v1/alerts")
@RequiredArgsConstructor
public class AlertController {

    private final AlertService alertService;

    @GetMapping("/findFirst")
    public AlertResult findFirst() { return alertService.findFirstSuspicious(); }

    @GetMapping("/findAny")
    public AlertResult findAny() { return alertService.findAnySuspicious(); }

    @GetMapping("/sequential")
    public AlertResult sequential() { return alertService.findFirstSequential(); }
}
