package com.bank.alert.service;

import org.junit.jupiter.api.RepeatedTest;
import org.junit.jupiter.api.Test;
import java.util.*;
import java.util.stream.*;
import static org.assertj.core.api.Assertions.*;

class FindFirstVsFindAnyTest {

    @Test
    void findFirstAlwaysReturnsSameInParallel() {
        List<Integer> data = IntStream.rangeClosed(1, 10_000).boxed().toList();
        Set<Integer> results = new HashSet<>();

        for (int i = 0; i < 20; i++) {
            int first = data.parallelStream().filter(n -> n > 5000).findFirst().orElse(-1);
            results.add(first);
        }
        // findFirst: always 5001 (deterministic)
        assertThat(results).containsExactly(5001);
    }

    @RepeatedTest(5)
    void findAnyMayReturnDifferentInParallel() {
        List<Integer> data = IntStream.rangeClosed(1, 10_000).boxed().toList();
        Set<Integer> results = new HashSet<>();

        for (int i = 0; i < 50; i++) {
            int any = data.parallelStream().filter(n -> n > 5000).findAny().orElse(-1);
            results.add(any);
        }
        // findAny: may return different values across runs
        // (all > 5000, but which specific one varies)
        assertThat(results).allMatch(n -> n > 5000);
        // Often returns different values:
        System.out.println("findAny returned " + results.size() + " distinct values: " + results);
    }

    @Test
    void bothIdenticalInSequential() {
        List<Integer> data = List.of(10, 20, 30, 40, 50);

        Optional<Integer> first = data.stream().filter(n -> n > 25).findFirst();
        Optional<Integer> any = data.stream().filter(n -> n > 25).findAny();

        assertThat(first).contains(30);
        assertThat(any).contains(30);  // same in sequential!
    }

    @Test
    void findFirstReturnsEmptyForNoMatch() {
        Optional<String> result = Stream.of("A", "B", "C")
            .filter(s -> s.equals("Z"))
            .findFirst();
        assertThat(result).isEmpty();
    }

    @Test
    void findAnyReturnsEmptyForNoMatch() {
        Optional<String> result = Stream.<String>empty().findAny();
        assertThat(result).isEmpty();
    }
}
